def cut_value(job, S):
    inside = set(S)
    cap = 0
    dem = 0
    for l, (u, v, _c) in enumerate(job.links):
        if (u in inside) != (v in inside):
            cap += job.c[l]
    for x in job.C:
        if x in inside:
            dem += job.demands[x]
    return cap, dem


