# plan construction

def _grow_tree(job, root, rem, res, rng, prefer_root_tail, mode=0, load=None):
    """Build one spanning out-branching on the participants from `root`."""
    C = job.C
    todo = [x for x in C if x != root]
    frontier = [root]
    edges = []
    emit_cache = {}
    in_cache = {}
    while todo:
        cands = []
        for u in frontier:
            eu = emit_cache.get(u)
            if eu is None:
                eu = job.emit_res(u, res)
                emit_cache[u] = eu
            for v in todo:
                aw = job._allowed(u, v)
                ub = job.out_bound(u, v, res, aw)
                if ub <= 0:
                    continue
                h = job.hops(u, v, res, aw)
                if h is None:
                    continue
                iv = in_cache.get(v)
                if iv is None:
                    iv = job.in_res(v, res)
                    in_cache[v] = iv
                cands.append((u, v, ub, h, eu, iv))
        if not cands:
            return None
        keyroot = 0 if prefer_root_tail else 1
        scored = []
        for (u, v, ub, h, eu, iv) in cands:
            isroot = 1 if u == root else 0
            capub = ub if ub < rem else rem
            jitter = rng.random()
            if mode == 0:
                rank = ((0 if isroot == keyroot else 1), -capub, h, jitter)
            elif mode == 1:
                rank = (h, -capub, (0 if isroot == keyroot else 1), jitter)
            elif mode == 2:
                rank = (-capub, h, (0 if isroot == keyroot else 1), jitter)
            elif mode == 3:
                # keep scarce participants: prefer tails with emission slack
                # and heads with inbound slack, without giving up hop count
                slack = eu if eu < iv else iv
                rank = (h, -slack, -capub, jitter)
            else:
                # spread the logical degree evenly, the binding constraint on
                # symmetric fabrics operating exactly at their cut bound
                if load is None:
                    rank = (h, -capub, jitter)
                else:
                    rank = (load[0].get(u, 0), load[1].get(v, 0), h, jitter)
            scored.append((rank + (u, v, ub, h), u, v, ub, h))
        scored.sort(key=lambda item: item[0])
        pick = scored[0]
        u, v = pick[1], pick[2]
        edges.append((u, v))
        frontier.append(v)
        todo.remove(v)
    return edges


def compile_plan(job, budget=None, seed=12345, allow_overflow=True):
    """Search for a valid PLAN; return it, or None when nothing is found."""
    if budget is None:
        budget = time_budget()
    deadline = time.monotonic() + budget
    C = job.C
    if len(C) < 2 or job.D <= 0:
        return None
    strategies = []
    for attempt in range(60):
        strategies.append((seed + attempt * 7919, attempt % 2 == 0, attempt % 4,
                          (4, 3, 3, 2)[attempt % 4]))
    for (sd, prefer_root_tail, order_mode, grow_mode) in strategies:
        if time.monotonic() > deadline:
            break
        rng = random.Random(sd)
        try:
            plan = _one_attempt(job, rng, prefer_root_tail, order_mode, deadline,
                                grow_mode)
        except Exception:
            plan = None
        if plan is not None and check_plan(job, plan):
            return plan
    if allow_overflow and time.monotonic() < deadline + 8.0:
        # Last resort: a structurally correct design produced without the
        # physical budget.  The controller reaches here only when the published
        # cut condition says the recurring job is admissible.
        plan = _overflow_plan(job, seed)
        if plan is not None:
            return plan
    return None


def _overflow_plan(job, seed):
    roomy = Job(job.n, job.links, job.demands, 1,
                {l: 1 for l in range(len(job.links))})
    roomy.c = [1 << 300] * len(job.links)
    roomy.arc_cap = []
    for _l in range(len(job.links)):
        roomy.arc_cap += [1 << 300, 1 << 300]
